#!/usr/bin/env python3
"""Offline finite-domain network rule mining service.

Reads exactly one JSON request on stdin and writes exactly one JSON response
on stdout.  See instruction.md for the full contract.
"""

import json
import math
import re
import sys

MAXBYTES = 8388608
MAXDEPTH = 64
I32MIN = -2147483648
I32MAX = 2147483647
SC = 840  # lcm(1..8): every value is carried exactly as 840 * true rational

NAME_RE = re.compile(r'[a-z][a-z0-9_]{0,31}')
TRACEID_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}')
IDVAL_RE = re.compile(r'[A-Za-z0-9_.:-]{1,32}')
STR_RE = re.compile(r'"(?:[^"\\\x00-\x1f]|\\(?:["\\/bfnrt]|u[0-9A-Fa-f]{4}))*"', re.S)
BRACK_RE = re.compile(r'[\[\]{}]')

NUMERIC = ('TIME', 'SIZE', 'COUNT')
ALLTYPES = ('TIME', 'SIZE', 'COUNT', 'ID', 'FLAG')
CMPOPS = ('eq', 'ne', 'lt', 'le', 'gt', 'ge')
AGGOPS = ('sum', 'mean', 'min', 'max')
CMPSYM = {'eq': '==', 'ne': '!=', 'lt': '<', 'le': '<=', 'gt': '>', 'ge': '>='}
TOPKEYS = {'version', 'schema', 'window', 'atoms', 'policy',
           'train', 'probes', 'queries'}


class JsonErr(Exception):
    pass


class SchemaErr(Exception):
    pass


def is_int(x):
    return type(x) is int


def is_str(x):
    return type(x) is str


def is_list(x):
    return type(x) is list


def is_dict(x):
    return type(x) is dict


# ----------------------------------------------------------------------------
# JSON layer
# ----------------------------------------------------------------------------

def _hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise JsonErr('duplicate key')
        d[k] = v
    return d


def _pf(s):
    v = float(s)
    if not math.isfinite(v):
        raise JsonErr('nonfinite')
    return v


def _pc(_s):
    raise JsonErr('constant')


def json_depth(text):
    """Maximum container nesting depth (root container == 1)."""
    stripped = STR_RE.sub('""', text)
    depth = 0
    mx = 0
    for m in BRACK_RE.finditer(stripped):
        if m.group() == '[' or m.group() == '{':
            depth += 1
            if depth > mx:
                mx = depth
        else:
            depth -= 1
    return mx


def parse_json_text(text):
    try:
        obj = json.loads(text, object_pairs_hook=_hook, parse_float=_pf,
                         parse_constant=_pc)
    except JsonErr:
        raise
    except RecursionError:
        raise JsonErr('deep')
    except Exception:
        raise JsonErr('bad')
    if json_depth(text) > MAXDEPTH:
        raise JsonErr('depth')
    return obj


# ----------------------------------------------------------------------------
# AST validation / compilation
# ----------------------------------------------------------------------------

def compile_term(node, inq, K, fidx, counter):
    """Validate a term, return (type, depth, python expression string).

    Numeric values are represented exactly as SC * true value, so all
    arithmetic stays in exact integers (SC is divisible by every window
    length in 1..8).
    """
    if not is_dict(node):
        raise SchemaErr('term')
    ks = set(node)
    if ks == {'field', 'at'}:
        counter[0] += 1
        nm = node['field']
        if not is_str(nm) or nm not in fidx:
            raise SchemaErr('field')
        fi, fty = fidx[nm]
        at = node['at']
        if at == '$':
            if not inq:
                raise SchemaErr('dollar')
            idx = '_d'
        else:
            if not is_int(at) or not 0 <= at < K:
                raise SchemaErr('at')
            idx = str(at)
        if fty in NUMERIC:
            return fty, 1, '(R[%s][%d]*%d)' % (idx, fi, SC)
        return fty, 1, 'R[%s][%d]' % (idx, fi)
    if ks == {'const', 'type'}:
        counter[0] += 1
        ty = node['type']
        if not is_str(ty) or ty not in ALLTYPES:
            raise SchemaErr('const type')
        v = node['const']
        if ty in NUMERIC:
            if not is_int(v) or not I32MIN <= v <= I32MAX:
                raise SchemaErr('const')
            return ty, 1, '(%d)' % (v * SC)
        if ty == 'ID':
            if not is_str(v) or not IDVAL_RE.fullmatch(v):
                raise SchemaErr('const id')
            return ty, 1, repr(v)
        if type(v) is not bool:
            raise SchemaErr('const flag')
        return ty, 1, ('True' if v else 'False')
    if ks == {'scale', 'term'}:
        counter[0] += 1
        s = node['scale']
        if not is_int(s) or not -1024 <= s <= 1024:
            raise SchemaErr('scale')
        ty, dep, e = compile_term(node['term'], inq, K, fidx, counter)
        if ty not in NUMERIC:
            raise SchemaErr('scale type')
        return ty, dep + 1, '(%d*(%s))' % (s, e)
    if ks == {'add'}:
        counter[0] += 1
        arr = node['add']
        if not is_list(arr) or len(arr) != 2:
            raise SchemaErr('add')
        t1, d1, e1 = compile_term(arr[0], inq, K, fidx, counter)
        t2, d2, e2 = compile_term(arr[1], inq, K, fidx, counter)
        if t1 not in NUMERIC or t1 != t2:
            raise SchemaErr('add type')
        return t1, (d1 if d1 > d2 else d2) + 1, '((%s)+(%s))' % (e1, e2)
    if ks == {'aggregate', 'field', 'from', 'to'}:
        counter[0] += 1
        op = node['aggregate']
        if not is_str(op) or op not in AGGOPS:
            raise SchemaErr('agg op')
        nm = node['field']
        if not is_str(nm) or nm not in fidx:
            raise SchemaErr('agg field')
        fi, fty = fidx[nm]
        if fty not in NUMERIC:
            raise SchemaErr('agg type')
        a = node['from']
        b = node['to']
        if not is_int(a) or not is_int(b) or not 0 <= a <= b < K:
            raise SchemaErr('agg range')
        items = ['R[%d][%d]' % (i, fi) for i in range(a, b + 1)]
        if op == 'sum':
            e = '((%s)*%d)' % ('+'.join(items), SC)
        elif op == 'mean':
            e = '((%s)*%d)' % ('+'.join(items), SC // (b - a + 1))
        elif op == 'min':
            e = '(min(%s)*%d)' % (', '.join(items), SC)
        else:
            e = '(max(%s)*%d)' % (', '.join(items), SC)
        return fty, 1, e
    raise SchemaErr('term form')


def compile_cmp(node, inq, K, fidx, counter):
    if not is_dict(node) or set(node) != {'cmp', 'left', 'right'}:
        raise SchemaErr('cmp form')
    op = node['cmp']
    if not is_str(op) or op not in CMPOPS:
        raise SchemaErr('cmp op')
    t1, d1, e1 = compile_term(node['left'], inq, K, fidx, counter)
    t2, d2, e2 = compile_term(node['right'], inq, K, fidx, counter)
    if t1 != t2:
        raise SchemaErr('cmp types')
    if t1 not in NUMERIC and op not in ('eq', 'ne'):
        raise SchemaErr('cmp op type')
    if d1 > 4 or d2 > 4:
        raise SchemaErr('depth')
    return '((%s)%s(%s))' % (e1, CMPSYM[op], e2)


def compile_atom(atom, K, fidx):
    """Validate one atom and return a callable rows -> bool."""
    if not is_dict(atom):
        raise SchemaErr('atom form')
    ks = set(atom)
    counter = [0]
    if ks == {'cmp', 'left', 'right'}:
        expr = compile_cmp(atom, False, K, fidx, counter)
        if counter[0] > 64:
            raise SchemaErr('nodes')
        src = 'def _f(R):\n    return ' + expr + '\n'
    elif ks == {'quantifier', 'from', 'to', 'predicate'}:
        q = atom['quantifier']
        if not is_str(q) or q not in ('any', 'all'):
            raise SchemaErr('quantifier')
        a = atom['from']
        b = atom['to']
        if not is_int(a) or not is_int(b) or not 0 <= a <= b < K:
            raise SchemaErr('quant range')
        pred = atom['predicate']
        if not is_dict(pred) or set(pred) != {'cmp', 'left', 'right'}:
            raise SchemaErr('quant body')
        expr = compile_cmp(pred, True, K, fidx, counter)
        if counter[0] > 64:
            raise SchemaErr('nodes')
        fn = 'any' if q == 'any' else 'all'
        src = ('def _f(R):\n    return %s(%s for _d in range(%d, %d))\n'
               % (fn, expr, a, b + 1))
    else:
        raise SchemaErr('atom keys')
    ns = {}
    exec(src, ns)  # noqa: S102 - generated from validated input only
    return ns['_f']


# ----------------------------------------------------------------------------
# Request validation and evaluation
# ----------------------------------------------------------------------------

def build_contexts(traces, K):
    """Contexts in partition order: trace array order, increasing end time."""
    out = []
    for tid, src, rows in traces:
        n = len(rows)
        if n < K:
            continue
        srt = sorted(rows, key=lambda r: r[0])
        vals = [r[1] for r in srt]
        ts = [r[0] for r in srt]
        for i in range(n - K + 1):
            out.append((tid, ts[i + K - 1], vals[i:i + K], src))
    return out


def parse_request(req):
    """Validate everything; return the pieces needed for computation."""
    if not is_dict(req) or set(req) != TOPKEYS:
        raise SchemaErr('top')
    if not is_int(req['version']) or req['version'] != 1:
        raise SchemaErr('version')
    K = req['window']
    if not is_int(K) or not 1 <= K <= 8:
        raise SchemaErr('window')
    pol = req['policy']
    if not is_dict(pol) or set(pol) != {'max_width', 'min_support',
                                        'min_witness'}:
        raise SchemaErr('policy')
    B = pol['max_width']
    S = pol['min_support']
    W = pol['min_witness']
    if not is_int(B) or not 1 <= B <= 4:
        raise SchemaErr('width')
    if not is_int(S) or not 1 <= S <= 4096:
        raise SchemaErr('support')
    if not is_int(W) or not 1 <= W <= 4096:
        raise SchemaErr('witness')

    schema = req['schema']
    if not is_list(schema) or not 1 <= len(schema) <= 32:
        raise SchemaErr('schema')
    nf = len(schema)
    ftypes = []
    flo = [0] * nf
    fhi = [0] * nf
    fdom = [None] * nf
    fidx = {}
    for i, fd in enumerate(schema):
        if not is_dict(fd):
            raise SchemaErr('field')
        ty = fd.get('type')
        if ty in NUMERIC:
            if set(fd) != {'name', 'type', 'min', 'max'}:
                raise SchemaErr('field keys')
            nm = fd['name']
            if not is_str(nm) or not NAME_RE.fullmatch(nm):
                raise SchemaErr('field name')
            lo = fd['min']
            hi = fd['max']
            if not is_int(lo) or not is_int(hi):
                raise SchemaErr('field bounds')
            if not I32MIN <= lo <= I32MAX or not I32MIN <= hi <= I32MAX:
                raise SchemaErr('field bounds')
            if lo > hi:
                raise SchemaErr('field bounds')
            flo[i] = lo
            fhi[i] = hi
        elif ty == 'ID':
            if set(fd) != {'name', 'type', 'values'}:
                raise SchemaErr('field keys')
            nm = fd['name']
            if not is_str(nm) or not NAME_RE.fullmatch(nm):
                raise SchemaErr('field name')
            vv = fd['values']
            if not is_list(vv) or not 1 <= len(vv) <= 32:
                raise SchemaErr('id values')
            dom = set()
            for v in vv:
                if not is_str(v) or not IDVAL_RE.fullmatch(v):
                    raise SchemaErr('id value')
                if v in dom:
                    raise SchemaErr('id dup')
                dom.add(v)
            fdom[i] = dom
        elif ty == 'FLAG':
            if set(fd) != {'name', 'type'}:
                raise SchemaErr('field keys')
            nm = fd['name']
            if not is_str(nm) or not NAME_RE.fullmatch(nm):
                raise SchemaErr('field name')
        else:
            raise SchemaErr('field type')
        if nm in fidx:
            raise SchemaErr('dup field')
        fidx[nm] = (i, ty)
        ftypes.append(ty)

    atoms_raw = req['atoms']
    if not is_list(atoms_raw) or len(atoms_raw) > 20:
        raise SchemaErr('atoms')
    atom_fns = [compile_atom(a, K, fidx) for a in atoms_raw]
    natoms = len(atom_fns)

    raw = {}
    for key in ('train', 'probes', 'queries'):
        arr = req[key]
        if not is_list(arr):
            raise SchemaErr(key)
        raw[key] = arr
    if sum(len(raw[k]) for k in raw) > 128:
        raise SchemaErr('traces')

    seen_ids = set()
    tsources = []
    tsrc_set = set()
    total_rows = 0
    parsed = {}
    for key in ('train', 'probes', 'queries'):
        lst = []
        for tr in raw[key]:
            if not is_dict(tr) or set(tr) != {'id', 'source', 'rows'}:
                raise SchemaErr('trace')
            tid = tr['id']
            src = tr['source']
            rows = tr['rows']
            if not is_str(tid) or not TRACEID_RE.fullmatch(tid):
                raise SchemaErr('trace id')
            if not is_str(src) or not TRACEID_RE.fullmatch(src):
                raise SchemaErr('trace source')
            if tid in seen_ids:
                raise SchemaErr('trace id dup')
            seen_ids.add(tid)
            if not is_list(rows):
                raise SchemaErr('rows')
            total_rows += len(rows)
            if total_rows > 16384:
                raise SchemaErr('rows total')
            times = set()
            kept = []
            for r in rows:
                if not is_dict(r) or set(r) != {'t', 'values'}:
                    raise SchemaErr('row')
                t = r['t']
                if not is_int(t) or not I32MIN <= t <= I32MAX:
                    raise SchemaErr('row t')
                if t in times:
                    raise SchemaErr('row t dup')
                times.add(t)
                vals = r['values']
                if not is_list(vals) or len(vals) != nf:
                    raise SchemaErr('row values')
                for i in range(nf):
                    v = vals[i]
                    ty = ftypes[i]
                    if ty == 'FLAG':
                        if type(v) is not bool:
                            raise SchemaErr('value')
                    elif ty == 'ID':
                        if not is_str(v) or v not in fdom[i]:
                            raise SchemaErr('value')
                    else:
                        if not is_int(v) or not flo[i] <= v <= fhi[i]:
                            raise SchemaErr('value')
                kept.append((t, vals))
            lst.append((tid, src, kept))
            if key == 'train' and src not in tsrc_set:
                tsrc_set.add(src)
                tsources.append(src)
        parsed[key] = lst
    if len(tsrc_set) > 16:
        raise SchemaErr('sources')

    train_ctx = build_contexts(parsed['train'], K)
    probe_ctx = build_contexts(parsed['probes'], K)
    query_ctx = build_contexts(parsed['queries'], K)
    if len(train_ctx) > 4096 or len(probe_ctx) > 128 or len(query_ctx) > 1024:
        raise SchemaErr('contexts')

    return (K, B, S, W, natoms, atom_fns, tsources, train_ctx, probe_ctx,
            query_ctx)


# ----------------------------------------------------------------------------
# Bit sliced counters (per query index, one count per class)
# ----------------------------------------------------------------------------

class BitCounters(object):
    __slots__ = ('cnt',)

    def __init__(self):
        self.cnt = []

    def add(self, mask):
        cnt = self.cnt
        i = 0
        while mask:
            if i == len(cnt):
                cnt.append(mask)
                return
            carry = cnt[i] & mask
            cnt[i] ^= mask
            mask = carry
            i += 1

    def counts(self, n):
        res = [0] * n
        for j, b in enumerate(self.cnt):
            if not b:
                continue
            bit = 1 << j
            while b:
                low = b & -b
                res[low.bit_length() - 1] |= bit
                b ^= low
        return res


# ----------------------------------------------------------------------------
# Mining
# ----------------------------------------------------------------------------

def compute(K, B, S, W, natoms, atom_fns, tsources, train_ctx, probe_ctx,
            query_ctx):
    ntrain = len(train_ctx)
    nprobe = len(probe_ctx)
    nquery = len(query_ctx)
    ns = len(tsources)

    # atom truth values ---------------------------------------------------
    ttrain = [[f(c[2]) for c in train_ctx] for f in atom_fns]
    tprobe = [[f(c[2]) for c in probe_ctx] for f in atom_fns]
    tquery = [[f(c[2]) for c in query_ctx] for f in atom_fns]

    ALLTRAIN = (1 << ntrain) - 1
    ALLPROBE = (1 << nprobe) - 1 if nprobe else -1
    QMASK = (1 << nquery) - 1

    # per literal truth bitmasks ------------------------------------------
    nlit = 2 * natoms
    lmask = [0] * nlit          # over training contexts
    lprobe = [0] * nlit         # over probe contexts
    lquery = [0] * nlit         # over query contexts
    for ai in range(natoms):
        tv = ttrain[ai]
        m = 0
        for ci, v in enumerate(tv):
            if v:
                m |= 1 << ci
        lmask[2 * ai] = m
        lmask[2 * ai + 1] = ALLTRAIN ^ m
        pv = tprobe[ai]
        m = 0
        for ci, v in enumerate(pv):
            if v:
                m |= 1 << ci
        lprobe[2 * ai] = m
        lprobe[2 * ai + 1] = ALLPROBE ^ m
        qv = tquery[ai]
        m = 0
        for ci, v in enumerate(qv):
            if v:
                m |= 1 << ci
        lquery[2 * ai] = m
        lquery[2 * ai + 1] = QMASK ^ m

    # sources --------------------------------------------------------------
    src_index = {}
    for i, s in enumerate(tsources):
        src_index[s] = i
    srcmask = [0] * ns
    for ci, c in enumerate(train_ctx):
        si = src_index[c[3]]
        srcmask[si] |= 1 << ci
    # per literal, per source masks
    lsrc = []
    for li in range(nlit):
        row = []
        for si in range(ns):
            row.append(lmask[li] & srcmask[si])
        lsrc.append(row)

    classes = {}
    if natoms > 0 and ns > 0 and nprobe > 0:
        # condition 2: per source support
        elig = []
        for li in range(nlit):
            ok = True
            row = lsrc[li]
            for si in range(ns):
                if row[si].bit_count() < S:
                    ok = False
                    break
            if ok:
                elig.append(li)
        if elig:
            elig_by_atom = [[], []] * 0  # placeholder replaced below
            elig_by_atom = []
            for ai in range(natoms):
                cur = []
                for li in (2 * ai, 2 * ai + 1):
                    if li in eligset_of(elig):
                        cur.append(li)
                elig_by_atom.append(cur)
            elig_atoms = [ai for ai in range(natoms) if elig_by_atom[ai]]

            def witnesses_ok(lits):
                k = len(lits)
                if k == 1:
                    row = lsrc[lits[0]]
                    for si in range(ns):
                        if row[si].bit_count() < W:
                            return False
                    return True
                for si in range(ns):
                    sm = srcmask[si]
                    ms = [lsrc[l][si] for l in lits]
                    suf = [0] * (k + 1)
                    for i in range(k - 1, -1, -1):
                        suf[i] = ms[i] | suf[i + 1]
                    pre = 0
                    for i in range(k):
                        others = pre | suf[i + 1]
                        if (ms[i] & (sm ^ others)).bit_count() < W:
                            return False
                        pre = pre | ms[i]
                return True

            def record(lits, psig):
                ct = 0
                for li in lits:
                    ct |= lquery[li]
                e = classes.get(psig)
                if e is None:
                    classes[psig] = [1, lits, ct, ct]
                else:
                    e[0] += 1
                    e[2] |= ct
                    e[3] &= ct

            def dfs(start, lits, cov, psig):
                if psig == ALLPROBE:
                    return
                if not witnesses_ok(lits):
                    return
                if cov == ALLTRAIN:
                    record(lits, psig)
                if len(lits) == B:
                    return
                for pos in range(start, len(elig_atoms)):
                    ai = elig_atoms[pos]
                    for li in elig_by_atom[ai]:
                        dfs(pos + 1, lits + (li,), cov | lmask[li],
                            psig | lprobe[li])

            dfs(0, (), 0, 0)

    # query answers ---------------------------------------------------------
    hexlen = (nprobe + 3) // 4
    out_classes = []
    mctr = BitCounters()
    yctr = BitCounters()
    for psig, entry in classes.items():
        cnt, repr_lits, oracc, andacc = entry
        out_classes.append({
            'signature': format(psig, 'x').zfill(hexlen),
            'members': cnt,
            'representative': {
                'or': [{'atom': li // 2, 'negated': (li % 2) == 1}
                       for li in repr_lits]
            },
        })
        if nquery:
            mctr.add(QMASK & ~oracc)
            yctr.add(QMASK & ~andacc)

    if nquery:
        mcounts = mctr.counts(nquery)
        ycounts = yctr.counts(nquery)
    else:
        mcounts = []
        ycounts = []

    out_queries = []
    for q in range(nquery):
        m = mcounts[q]
        y = ycounts[q]
        if m > 0:
            st = 'violating'
        elif y > 0:
            st = 'ambiguous'
        else:
            st = 'consistent'
        out_queries.append({'trace': query_ctx[q][0], 'end': query_ctx[q][1],
                            'must': m, 'may': y, 'status': st})

    return {'version': 1, 'classes': out_classes, 'queries': out_queries}


def eligset_of(elig):
    return set(elig)


# ----------------------------------------------------------------------------
# Driver
# ----------------------------------------------------------------------------

def emit(obj):
    sys.stdout.write(json.dumps(obj, separators=(',', ':')))
    sys.stdout.write('\n')


def main():
    data = sys.stdin.buffer.read()
    if len(data) > MAXBYTES:
        emit({'error': 'E_LIMIT'})
        return
    try:
        text = data.decode('utf-8')
