#!/usr/bin/env python3
"""Independent, deliberately naive reference implementation for testing.

Uses Fraction arithmetic and closure-based term evaluation, and brute-force
clause enumeration with plain per-context loops.
"""
import json, math, re, sys
from fractions import Fraction

MAXBYTES = 8388608
I32MIN, I32MAX = -2**31, 2**31-1
NAME_RE = re.compile(r'[a-z][a-z0-9_]{0,31}')
TID_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}')
IDVAL_RE = re.compile(r'[A-Za-z0-9_.:-]{1,32}')
STR_RE = re.compile(r'"(?:[^"\\\x00-\x1f]|\\(?:["\\/bfnrt]|u[0-9A-Fa-f]{4}))*"', re.S)
BRACK_RE = re.compile(r'[\[\]{}]')
NUM = ('TIME','SIZE','COUNT')
ALLT = ('TIME','SIZE','COUNT','ID','FLAG')

class JsonErr(Exception): pass
class SchemaErr(Exception): pass

def is_int(x): return type(x) is int
def is_str(x): return type(x) is str
def is_list(x): return type(x) is list
def is_dict(x): return type(x) is dict

def _hook(pairs):
    d={}
    for k,v in pairs:
        if k in d: raise JsonErr()
        d[k]=v
    return d
def _pf(s):
    v=float(s)
    if not math.isfinite(v): raise JsonErr()
    return v
def _pc(s): raise JsonErr()

def depth_of(text):
    st = STR_RE.sub('""', text)
    d=0; mx=0
    for m in BRACK_RE.finditer(st):
        if m.group() in '[{':
            d+=1; mx=max(mx,d)
        else: d-=1
    return mx

def parse(text):
    try:
        obj = json.loads(text, object_pairs_hook=_hook, parse_float=_pf, parse_constant=_pc)
    except JsonErr: raise
    except RecursionError: raise JsonErr()
    except Exception: raise JsonErr()
    if depth_of(text) > 64: raise JsonErr()
    return obj

# ---- term evaluation (closures, Fraction) ----
def mk_term(node, inq, K, fidx, counter):
    if not is_dict(node): raise SchemaErr()
    ks=set(node)
    if ks == {'field','at'}:
        counter[0]+=1
        nm=node['field']
        if not is_str(nm) or nm not in fidx: raise SchemaErr()
        fi,fty=fidx[nm]
        at=node['at']
        if at == '$':
            if not inq: raise SchemaErr()
            def f(R,d,fi=fi,fty=fty):
                v=R[d][fi]
                return Fraction(v) if fty in NUM else v
            return fty,1,f
        if not is_int(at) or not 0<=at<K: raise SchemaErr()
        def f(R,d,fi=fi,at=at,fty=fty):
            v=R[at][fi]
            return Fraction(v) if fty in NUM else v
        return fty,1,f
    if ks == {'const','type'}:
        counter[0]+=1
        ty=node['type']
        if not is_str(ty) or ty not in ALLT: raise SchemaErr()
        v=node['const']
        if ty in NUM:
            if not is_int(v) or not I32MIN<=v<=I32MAX: raise SchemaErr()
            return ty,1,(lambda R,d,v=Fraction(v): v)
        if ty=='ID':
            if not is_str(v) or not IDVAL_RE.fullmatch(v): raise SchemaErr()
            return ty,1,(lambda R,d,v=v: v)
        if type(v) is not bool: raise SchemaErr()
        return ty,1,(lambda R,d,v=v: v)
    if ks == {'scale','term'}:
        counter[0]+=1
        s=node['scale']
        if not is_int(s) or not -1024<=s<=1024: raise SchemaErr()
        ty,dep,g=mk_term(node['term'],inq,K,fidx,counter)
        if ty not in NUM: raise SchemaErr()
        return ty,dep+1,(lambda R,d,s=s,g=g: s*g(R,d))
    if ks == {'add'}:
        counter[0]+=1
        arr=node['add']
        if not is_list(arr) or len(arr)!=2: raise SchemaErr()
        t1,d1,g1=mk_term(arr[0],inq,K,fidx,counter)
        t2,d2,g2=mk_term(arr[1],inq,K,fidx,counter)
        if t1 not in NUM or t1!=t2: raise SchemaErr()
        return t1,max(d1,d2)+1,(lambda R,d,g1=g1,g2=g2: g1(R,d)+g2(R,d))
    if ks == {'aggregate','field','from','to'}:
        counter[0]+=1
        op=node['aggregate']
        if not is_str(op) or op not in ('sum','mean','min','max'): raise SchemaErr()
        nm=node['field']
        if not is_str(nm) or nm not in fidx: raise SchemaErr()
        fi,fty=fidx[nm]
        if fty not in NUM: raise SchemaErr()
        a=node['from']; b=node['to']
        if not is_int(a) or not is_int(b) or not 0<=a<=b<K: raise SchemaErr()
        rng=list(range(a,b+1))
        if op=='sum':
            def f(R,d,fi=fi,rng=rng):
                return Fraction(sum(R[i][fi] for i in rng))
        elif op=='mean':
            def f(R,d,fi=fi,rng=rng):
                return Fraction(sum(R[i][fi] for i in rng), len(rng))
        elif op=='min':
            def f(R,d,fi=fi,rng=rng):
                return Fraction(min(R[i][fi] for i in rng))
        else:
            def f(R,d,fi=fi,rng=rng):
                return Fraction(max(R[i][fi] for i in rng))
        return fty,1,f
    raise SchemaErr()

OPS={'eq':lambda x,y:x==y,'ne':lambda x,y:x!=y,'lt':lambda x,y:x<y,
     'le':lambda x,y:x<=y,'gt':lambda x,y:x>y,'ge':lambda x,y:x>=y}

def mk_cmp(node, inq, K, fidx, counter):
    if not is_dict(node) or set(node)!={'cmp','left','right'}: raise SchemaErr()
    op=node['cmp']
    if not is_str(op) or op not in OPS: raise SchemaErr()
    t1,d1,f1=mk_term(node['left'],inq,K,fidx,counter)
    t2,d2,f2=mk_term(node['right'],inq,K,fidx,counter)
    if t1!=t2: raise SchemaErr()
    if t1 not in NUM and op not in ('eq','ne'): raise SchemaErr()
    if d1>4 or d2>4: raise SchemaErr()
    o=OPS[op]
    return lambda R,d,f1=f1,f2=f2,o=o: o(f1(R,d),f2(R,d))

def mk_atom(atom,K,fidx):
    if not is_dict(atom): raise SchemaErr()
    ks=set(atom)
    counter=[0]
    if ks=={'cmp','left','right'}:
        body=mk_cmp(atom,False,K,fidx,counter)
        if counter[0]>64: raise SchemaErr()
        return lambda R: body(R,None)
    if ks=={'quantifier','from','to','predicate'}:
        q=atom['quantifier']
        if not is_str(q) or q not in ('any','all'): raise SchemaErr()
        a=atom['from']; b=atom['to']
        if not is_int(a) or not is_int(b) or not 0<=a<=b<K: raise SchemaErr()
        pred=atom['predicate']
        if not is_dict(pred) or set(pred)!={'cmp','left','right'}: raise SchemaErr()
        body=mk_cmp(pred,True,K,fidx,counter)
        if counter[0]>64: raise SchemaErr()
        if q=='any':
            def f(R,body=body,a=a,b=b):
                for i in range(a,b+1):
                    if body(R,i): return True
                return False
        else:
            def f(R,body=body,a=a,b=b):
                for i in range(a,b+1):
                    if not body(R,i): return False
                return True
        return f
    raise SchemaErr()

def build(req):
    if not is_dict(req) or set(req)!={'version','schema','window','atoms','policy','train','probes','queries'}: raise SchemaErr()
    if not is_int(req['version']) or req['version']!=1: raise SchemaErr()
    K=req['window']
    if not is_int(K) or not 1<=K<=8: raise SchemaErr()
    pol=req['policy']
    if not is_dict(pol) or set(pol)!={'max_width','min_support','min_witness'}: raise SchemaErr()
    B=pol['max_width']; S=pol['min_support']; W=pol['min_witness']
    if not is_int(B) or not 1<=B<=4: raise SchemaErr()
    if not is_int(S) or not 1<=S<=4096: raise SchemaErr()
    if not is_int(W) or not 1<=W<=4096: raise SchemaErr()
    schema=req['schema']
    if not is_list(schema) or not 1<=len(schema)<=32: raise SchemaErr()
    nf=len(schema)
    ftypes=[]; flo=[0]*nf; fhi=[0]*nf; fdom=[None]*nf; fidx={}
    for i,fd in enumerate(schema):
        if not is_dict(fd): raise SchemaErr()
        ty=fd.get('type')
        if ty in NUM:
            if set(fd)!={'name','type','min','max'}: raise SchemaErr()
            nm=fd['name']
            if not is_str(nm) or not NAME_RE.fullmatch(nm): raise SchemaErr()
            lo=fd['min']; hi=fd['max']
            if not is_int(lo) or not is_int(hi): raise SchemaErr()
            if not I32MIN<=lo<=I32MAX or not I32MIN<=hi<=I32MAX: raise SchemaErr()
            if lo>hi: raise SchemaErr()
            flo[i]=lo; fhi[i]=hi
        elif ty=='ID':
            if set(fd)!={'name','type','values'}: raise SchemaErr()
            nm=fd['name']
            if not is_str(nm) or not NAME_RE.fullmatch(nm): raise SchemaErr()
            vv=fd['values']
            if not is_list(vv) or not 1<=len(vv)<=32: raise SchemaErr()
            dom=set()
            for v in vv:
                if not is_str(v) or not IDVAL_RE.fullmatch(v): raise SchemaErr()
                if v in dom: raise SchemaErr()
                dom.add(v)
            fdom[i]=dom
        elif ty=='FLAG':
            if set(fd)!={'name','type'}: raise SchemaErr()
            nm=fd['name']
            if not is_str(nm) or not NAME_RE.fullmatch(nm): raise SchemaErr()
