            total+=len(rows)
            if total>16384: raise SchemaErr()
            times=set(); kept=[]
            for r in rows:
                if not is_dict(r) or set(r)!={'t','values'}: raise SchemaErr()
                t=r['t']
                if not is_int(t) or not I32MIN<=t<=I32MAX: raise SchemaErr()
                if t in times: raise SchemaErr()
                times.add(t)
                vals=r['values']
                if not is_list(vals) or len(vals)!=nf: raise SchemaErr()
                for i in range(nf):
                    v=vals[i]; ty=ftypes[i]
