#!/usr/bin/env python3
"""Offline finite-domain network rule mining service.

Reads exactly one JSON request on stdin and writes exactly one JSON response
on stdout.  See instruction.md for the full contract.
"""

import json
import math
import re
import sys

MAXBYTES = 8388608
MAXDEPTH = 64
I32MIN = -2147483648
I32MAX = 2147483647
SC = 840  # lcm(1..8): every value is carried exactly as 840 * true rational

NAME_RE = re.compile(r'[a-z][a-z0-9_]{0,31}')
TRACEID_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}')
IDVAL_RE = re.compile(r'[A-Za-z0-9_.:-]{1,32}')
STR_RE = re.compile(r'"(?:[^"\\\x00-\x1f]|\\(?:["\\/bfnrt]|u[0-9A-Fa-f]{4}))*"', re.S)
BRACK_RE = re.compile(r'[\[\]{}]')

NUMERIC = ('TIME', 'SIZE', 'COUNT')
ALLTYPES = ('TIME', 'SIZE', 'COUNT', 'ID', 'FLAG')
CMPOPS = ('eq', 'ne', 'lt', 'le', 'gt', 'ge')
AGGOPS = ('sum', 'mean', 'min', 'max')
CMPSYM = {'eq': '==', 'ne': '!=', 'lt': '<', 'le': '<=', 'gt': '>', 'ge': '>='}
TOPKEYS = {'version', 'schema', 'window', 'atoms', 'policy',
           'train', 'probes', 'queries'}


class JsonErr(Exception):
    pass


class SchemaErr(Exception):
    pass


def is_int(x):
    return type(x) is int


def is_str(x):
    return type(x) is str


def is_list(x):
    return type(x) is list


def is_dict(x):
    return type(x) is dict


# ----------------------------------------------------------------------------
# JSON layer
# ----------------------------------------------------------------------------

def _hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise JsonErr('duplicate key')
        d[k] = v
    return d


def _pf(s):
    v = float(s)
    if not math.isfinite(v):
        raise JsonErr('nonfinite')
    return v


def _pc(_s):
    raise JsonErr('constant')


def json_depth(text):
    """Maximum container nesting depth (root container == 1)."""
    stripped = STR_RE.sub('""', text)
    depth = 0
    mx = 0
    for m in BRACK_RE.finditer(stripped):
        if m.group() == '[' or m.group() == '{':
            depth += 1
            if depth > mx:
                mx = depth
        else:
            depth -= 1
    return mx


def parse_json_text(text):
    try:
        obj = json.loads(text, object_pairs_hook=_hook, parse_float=_pf,
                         parse_constant=_pc)
    except JsonErr:
        raise
    except RecursionError:
        raise JsonErr('deep')
    except Exception:
        raise JsonErr('bad')
    if json_depth(text) > MAXDEPTH:
        raise JsonErr('depth')
    return obj


# ----------------------------------------------------------------------------
# AST validation / compilation
# ----------------------------------------------------------------------------

def compile_term(node, inq, K, fidx, counter):
    """Validate a term, return (type, depth, python expression string).

    Numeric values are represented exactly as SC * true value, so all
    arithmetic stays in exact integers (SC is divisible by every window
    length in 1..8).
    """
    if not is_dict(node):
        raise SchemaErr('term')
    ks = set(node)
    if ks == {'field', 'at'}:
        counter[0] += 1
        nm = node['field']
        if not is_str(nm) or nm not in fidx:
            raise SchemaErr('field')
        fi, fty = fidx[nm]
        at = node['at']
        if at == '$':
            if not inq:
                raise SchemaErr('dollar')
            idx = '_d'
        else:
            if not is_int(at) or not 0 <= at < K:
                raise SchemaErr('at')
            idx = str(at)

            cnt[i] ^= mask
            mask = carry
            i += 1

    def counts(self, n):
        res = [0] * n
        for j, b in enumerate(self.cnt):
            if not b:
                continue
            bit = 1 << j
            while b:
                low = b & -b
                res[low.bit_length() - 1] |= bit
                b ^= low
        return res


# ----------------------------------------------------------------------------
# Mining
# ----------------------------------------------------------------------------

def compute(K, B, S, W, natoms, atom_fns, tsources, train_ctx, probe_ctx,
            query_ctx):
    ntrain = len(train_ctx)
    nprobe = len(probe_ctx)
    nquery = len(query_ctx)
    ns = len(tsources)

    # atom truth values ---------------------------------------------------
    ttrain = [[f(c[2]) for c in train_ctx] for f in atom_fns]
    tprobe = [[f(c[2]) for c in probe_ctx] for f in atom_fns]
    tquery = [[f(c[2]) for c in query_ctx] for f in atom_fns]

    ALLTRAIN = (1 << ntrain) - 1
    ALLPROBE = (1 << nprobe) - 1 if nprobe else -1
    QMASK = (1 << nquery) - 1

    # per literal truth bitmasks ------------------------------------------
    nlit = 2 * natoms
    lmask = [0] * nlit          # over training contexts
    lprobe = [0] * nlit         # over probe contexts
    lquery = [0] * nlit         # over query contexts
    for ai in range(natoms):
        tv = ttrain[ai]
        m = 0
        for ci, v in enumerate(tv):
            if v:
                m |= 1 << ci
        lmask[2 * ai] = m
        lmask[2 * ai + 1] = ALLTRAIN ^ m
        pv = tprobe[ai]
        m = 0
        for ci, v in enumerate(pv):
            if v:
                m |= 1 << ci
        lprobe[2 * ai] = m
        lprobe[2 * ai + 1] = ALLPROBE ^ m
        qv = tquery[ai]
        m = 0
        for ci, v in enumerate(qv):
            if v:
                m |= 1 << ci
        lquery[2 * ai] = m
        lquery[2 * ai + 1] = QMASK ^ m

    # sources --------------------------------------------------------------
    src_index = {}
    for i, s in enumerate(tsources):
        src_index[s] = i
    srcmask = [0] * ns
    for ci, c in enumerate(train_ctx):
        si = src_index[c[3]]
        srcmask[si] |= 1 << ci
    # per literal, per source masks
    lsrc = []
    for li in range(nlit):
        row = []
        for si in range(ns):
            row.append(lmask[li] & srcmask[si])
        lsrc.append(row)

    classes = {}
    if natoms > 0 and ns > 0 and nprobe > 0:
        # condition 2: per source support
        elig = []
        for li in range(nlit):
            ok = True
            row = lsrc[li]
            for si in range(ns):
                if row[si].bit_count() < S:
                    ok = False
                    break
            if ok:
                elig.append(li)
        elig_set = set(elig)
        if elig:
            elig_by_atom = []
            for ai in range(natoms):
                cur = []
                for li in (2 * ai, 2 * ai + 1):
                    if li in elig_set:
                        cur.append(li)
                elig_by_atom.append(cur)
            elig_atoms = [ai for ai in range(natoms) if elig_by_atom[ai]]

            def witnesses_ok(lits):
                k = len(lits)
                if k == 1:
                    row = lsrc[lits[0]]
                    for si in range(ns):
                        if row[si].bit_count() < W:
                            return False
                    return True
                for si in range(ns):
                    sm = srcmask[si]
                    ms = [lsrc[l][si] for l in lits]
                    suf = [0] * (k + 1)
                    for i in range(k - 1, -1, -1):
                        suf[i] = ms[i] | suf[i + 1]
                    pre = 0
                    for i in range(k):
                        others = pre | suf[i + 1]
                        if (ms[i] & (sm ^ others)).bit_count() < W:
                            return False
                        pre = pre | ms[i]
                return True

            def record(lits, psig):
                ct = 0
                for li in lits:
                    ct |= lquery[li]
                e = classes.get(psig)
                if e is None:
                    classes[psig] = [1, lits, ct, ct]
                else:
                    e[0] += 1
                    e[2] |= ct
                    e[3] &= ct

            def dfs(start, lits, cov, psig):
                if psig == ALLPROBE:
                    return
                if not witnesses_ok(lits):
                    return
                if cov == ALLTRAIN:
                    record(lits, psig)
                if len(lits) == B:
                    return
                for pos in range(start, len(elig_atoms)):
                    ai = elig_atoms[pos]
                    for li in elig_by_atom[ai]:
                        dfs(pos + 1, lits + (li,), cov | lmask[li],
                            psig | lprobe[li])

            dfs(0, (), 0, 0)

    # query answers ---------------------------------------------------------
    hexlen = (nprobe + 3) // 4
    out_classes = []
    mctr = BitCounters()
    yctr = BitCounters()
    for psig, entry in classes.items():
        cnt, repr_lits, oracc, andacc = entry
        out_classes.append({
            'signature': format(psig, 'x').zfill(hexlen),
            'members': cnt,
            'representative': {
                'or': [{'atom': li // 2, 'negated': (li % 2) == 1}
                       for li in repr_lits]
            },
        })
        if nquery:
            mctr.add(QMASK & ~oracc)
            yctr.add(QMASK & ~andacc)

    if nquery:
        mcounts = mctr.counts(nquery)
        ycounts = yctr.counts(nquery)
    else:
        mcounts = []
        ycounts = []

    out_queries = []
    for q in range(nquery):
        m = mcounts[q]
        y = ycounts[q]
        if m > 0:
            st = 'violating'
        elif y > 0:
            st = 'ambiguous'
        else:
            st = 'consistent'
        out_queries.append({'trace': query_ctx[q][0], 'end': query_ctx[q][1],
                            'must': m, 'may': y, 'status': st})

    return {'version': 1, 'classes': out_classes, 'queries': out_queries}


# ----------------------------------------------------------------------------
# Driver
# ----------------------------------------------------------------------------

def emit(obj):
    sys.stdout.write(json.dumps(obj, separators=(',', ':')))
    sys.stdout.write('\n')


def main():
    data = sys.stdin.buffer.read()
    if len(data) > MAXBYTES:
        emit({'error': 'E_LIMIT'})

if got != want:
    # numeric compare via fraction
    from fractions import Fraction
    if tty in NUM:
        if Fraction(got, 840) != want:
            print('MISMATCH', term, got, want, rows); bad += 1
    else:
        print('MISMATCH', term, got, want, rows); bad += 1
if cnt[0] != cnt2[0]:
    print('NODECOUNT', term, cnt[0], cnt2[0]); bad += 1

