        raise SchemaErr('cmp form')
    op = node['cmp']
    if not is_str(op) or op not in CMPOPS:
        raise SchemaErr('cmp op')
    t1, d1, e1 = compile_term(node['left'], inq, K, fidx, counter)
    t2, d2, e2 = compile_term(node['right'], inq, K, fidx, counter)
    if t1 != t2:
        raise SchemaErr('cmp types')
    if t1 not in NUMERIC and op not in ('eq', 'ne'):
        raise SchemaErr('cmp op type')
    if d1 > 4 or d2 > 4:
        raise SchemaErr('depth')
    return '((%s)%s(%s))' % (e1, CMPSYM[op], e2)


def compile_atom(atom, K, fidx):
    """Validate one atom and return a callable rows -> bool."""
    if not is_dict(atom):
        raise SchemaErr('atom form')
    ks = set(atom)
    counter = [0]
    if ks == {'cmp', 'left', 'right'}:
        expr = compile_cmp(atom, False, K, fidx, counter)
        if counter[0] > 64:
            raise SchemaErr('nodes')
        src = 'def _f(R):\n    return ' + expr + '\n'
    elif ks == {'quantifier', 'from', 'to', 'predicate'}:
        q = atom['quantifier']
        if not is_str(q) or q not in ('any', 'all'):
            raise SchemaErr('quantifier')
        a = atom['from']
        b = atom['to']
        if not is_int(a) or not is_int(b) or not 0 <= a <= b < K:
            raise SchemaErr('quant range')
        pred = atom['predicate']
        if not is_dict(pred) or set(pred) != {'cmp', 'left', 'right'}:
            raise SchemaErr('quant body')
        expr = compile_cmp(pred, True, K, fidx, counter)
        if counter[0] > 64:
            raise SchemaErr('nodes')
        fn = 'any' if q == 'any' else 'all'
        src = ('def _f(R):\n    return %s(%s for _d in range(%d, %d))\n'
               % (fn, expr, a, b + 1))
    else:
        raise SchemaErr('atom keys')
    ns = {}
    exec(src, ns)  # noqa: S102 - generated from validated input only
    return ns['_f']


# ----------------------------------------------------------------------------
# Request validation and evaluation
# ----------------------------------------------------------------------------

def build_contexts(traces, K):
    """Contexts in partition order: trace array order, increasing end time."""
    out = []
    for tid, src, rows in traces:
        n = len(rows)
        if n < K:
            continue
        srt = sorted(rows, key=lambda r: r[0])
        vals = [r[1] for r in srt]
        ts = [r[0] for r in srt]
        for i in range(n - K + 1):
            out.append((tid, ts[i + K - 1], vals[i:i + K], src))
    return out


def parse_request(req):
    """Validate everything; return the pieces needed for computation."""
    if not is_dict(req) or set(req) != TOPKEYS:
        raise SchemaErr('top')
    if not is_int(req['version']) or req['version'] != 1:
        raise SchemaErr('version')
    K = req['window']
    if not is_int(K) or not 1 <= K <= 8:
        raise SchemaErr('window')
    pol = req['policy']
    if not is_dict(pol) or set(pol) != {'max_width', 'min_support',
                                        'min_witness'}:
        raise SchemaErr('policy')
    B = pol['max_width']
    S = pol['min_support']
    W = pol['min_witness']

