#!/usr/bin/env python3
"""Check structural invariants of responses over many random requests."""
import json, subprocess, random, sys
sys.path.insert(0, '/app/dev')
import gen, gen2, gen3, gen4

bad = 0
checked = 0
for seed in range(1500):
    rng = random.Random(seed + 77777)
    g = [gen, gen2, gen3, gen4][seed % 4]
    req = g.gen_request(rng)
    p = subprocess.run(['python3', '/app/submission/main.py'],
                       input=json.dumps(req).encode(), capture_output=True)
    if p.returncode != 0:
        print('rc fail', seed); bad += 1; continue
    r = json.loads(p.stdout)
    # probe context count for signature length
    K = req['window']
    def nctx(traces):
        return sum(max(0, len(t['rows']) - K + 1) for t in traces)
    P = nctx(req['probes'])
    B = req['policy']['max_width']
    if set(r.keys()) != {'version', 'classes', 'queries'}:
        print('keys', seed, r.keys()); bad += 1; continue
    if r['version'] != 1:
        print('version', seed); bad += 1; continue
    sigs = set()
    for c in r['classes']:
        if set(c.keys()) != {'signature', 'members', 'representative'}:
            print('class keys', seed); bad += 1; break
        if c['members'] < 1: print('members', seed); bad += 1; break
        if len(c['signature']) != max(1, (P + 3) // 4):
            print('sig len', seed, c['signature'], P); bad += 1; break
        if c['signature'] != c['signature'].lower():
            print('sig case', seed); bad += 1; break
        if c['signature'] in sigs: print('dup sig', seed); bad += 1; break
        sigs.add(c['signature'])
        orl = c['representative']['or']
        if not (1 <= len(orl) <= B): print('width', seed, len(orl)); bad += 1; break
        atoms = [l['atom'] for l in orl]
        if len(set(atoms)) != len(atoms): print('dup atom in clause', seed); bad += 1; break
        if any(a < 0 or a >= len(req['atoms']) for a in atoms):
            print('atom idx', seed); bad += 1; break
        for l in orl:
            if set(l.keys()) != {'atom', 'negated'} or type(l['negated']) is not bool:
                print('literal', seed, l); bad += 1; break
    # queries
    exp_q = nctx(req['queries'])
    if len(r['queries']) != exp_q:
        print('query count', seed, len(r['queries']), exp_q); bad += 1; continue
    for q in r['queries']:
        if set(q.keys()) != {'trace', 'end', 'must', 'may', 'status'}:
            print('query keys', seed); bad += 1; break
        if not (0 <= q['must'] <= q['may'] <= len(r['classes'])):
            print('must/may', seed, q); bad += 1; break
        exp = 'violating' if q['must'] > 0 else ('ambiguous' if q['may'] > 0 else 'consistent')
        if q['status'] != exp:
            print('status', seed, q); bad += 1; break
    checked += 1
print('checked', checked, 'bad', bad)
